// apps/tap-flip/src/rules/scramble-board.ts
import { nextInt, seedRng } from '@e07/game-kit/rng/sfc32.ts';

/** A generation helper only create() calls: its draws happen before play. */
export function scrambleCell(seed: number, size: number): number {
  return nextInt(seedRng(seed), size).value;
}
